-- ============================================================================
-- D1 PROFESSIONAL DEEP SEED: Oilfield Data Quality, intermediate tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/dataqc/intermediate.
--
-- What this tier owns: WHICH VALUES STAND APART, the plausibility dimension.
-- The z-score with the sample standard deviation and its ceiling
-- (n - 1) / sqrt(n); the median, the raw MAD and the modified z-score with
-- 0.6745 as printed; the R6, R7 and R8 quantile rules and Tukey fences; the
-- Hampel window with its edges, gaps and thin windows; Grubbs for one outlier
-- and the masking a second one causes; the Mahalanobis distance with a
-- chi-square cutoff on classical estimates. Digest sections 17 to 24, and
-- section 32.
--
-- THE TRAP THE TIER IS BUILT ON. Each method answers its own question, and an
-- outlier helps set the mean and SD that measure it. The Professional capstone
-- grades six plausibility quantities and grades no chart and no scorecard.
-- ============================================================================

values ('dataqc', 'intermediate', '{"modules":[{"key":"m01-the-z-score-and-its-ceiling","title":"The z-Score and Its Ceiling","lesson_keys":["l01-a-distance-in-standard-deviations","l02-sample-or-population","l03-the-largest-possible-z","l04-one-outlier-inflates-the-spread"]},{"key":"m02-the-median-and-the-mad","title":"The Median and the MAD","lesson_keys":["l01-a-centre-outliers-barely-move","l02-the-median-absolute-deviation","l03-the-modified-z-score","l04-the-printed-constant","l05-when-the-mad-is-zero"]},{"key":"m03-quartiles-and-fences","title":"Quartiles and Tukey Fences","lesson_keys":["l01-three-quantile-rules","l02-the-inner-fences","l03-far-out-values","l04-on-the-fence-is-inside"]},{"key":"m04-a-moving-window","title":"A Moving Window","lesson_keys":["l01-local-against-global","l02-the-hampel-window","l03-edges-gaps-and-thin-windows","l04-flag-or-replace"]},{"key":"m05-formal-tests-and-many-variables","title":"Formal Tests and Many Variables","lesson_keys":["l01-grubbs-for-one-outlier","l02-the-critical-value","l03-masking","l04-the-mahalanobis-distance","l05-the-chi-square-cutoff"]},{"key":"m06-outliers-in-a-report","title":"Outliers in a Report","lesson_keys":["l01-the-nist-worked-examples","l02-which-method-for-which-question","l03-a-flag-is-a-question","l04-the-capstone-brief"]}]}'::jsonb, 1)
